CREATE TABLE public.user_blocks (blocker_id uuid NOT NULL, blocked_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(blocker_id, blocked_id), CHECK (blocker_id <> blocked_id));
GRANT SELECT, INSERT, DELETE ON public.user_blocks TO authenticated;
GRANT ALL ON public.user_blocks TO service_role;
ALTER TABLE public.user_blocks ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own block list" ON public.user_blocks FOR SELECT TO authenticated USING (blocker_id=auth.uid());
CREATE POLICY "Block as self" ON public.user_blocks FOR INSERT TO authenticated WITH CHECK (blocker_id=auth.uid());
CREATE POLICY "Unblock as self" ON public.user_blocks FOR DELETE TO authenticated USING (blocker_id=auth.uid());
CREATE INDEX user_blocks_reverse ON public.user_blocks(blocked_id,blocker_id);
CREATE TABLE public.hidden_posts (user_id uuid NOT NULL, post_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,post_id));
GRANT SELECT, INSERT, DELETE ON public.hidden_posts TO authenticated;
GRANT ALL ON public.hidden_posts TO service_role;
ALTER TABLE public.hidden_posts ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own hidden posts" ON public.hidden_posts FOR ALL TO authenticated USING (user_id=auth.uid()) WITH CHECK (user_id=auth.uid());
CREATE TABLE public.content_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reporter_id uuid NOT NULL, reported_user_id uuid NOT NULL, target_type text NOT NULL CHECK(target_type IN ('user','post','comment')), target_id uuid, group_id uuid NOT NULL REFERENCES public.groups(id), reason text NOT NULL CHECK(reason IN ('inappropriate_media','harassment','hate_or_threats','spam_or_fake','other')), details text CHECK(length(details)<=500), status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','removed','dismissed')), created_at timestamptz NOT NULL DEFAULT now(), reviewed_at timestamptz);
GRANT INSERT ON public.content_reports TO authenticated;
GRANT ALL ON public.content_reports TO service_role;
ALTER TABLE public.content_reports ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Submit own report" ON public.content_reports FOR INSERT TO authenticated WITH CHECK(reporter_id=auth.uid() AND reporter_id<>reported_user_id AND is_group_member(group_id,auth.uid()) AND is_group_member(group_id,reported_user_id) AND status='open' AND reviewed_at IS NULL);
CREATE INDEX content_reports_open ON public.content_reports(status,created_at DESC);
CREATE FUNCTION public.safety_blocked_pairs(_user_id uuid) RETURNS TABLE(user_id uuid) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT blocked_id FROM user_blocks WHERE blocker_id=_user_id AND (_user_id=auth.uid() OR auth.role()='service_role') UNION SELECT blocker_id FROM user_blocks WHERE blocked_id=_user_id AND (_user_id=auth.uid() OR auth.role()='service_role') $$;
REVOKE ALL ON FUNCTION public.safety_blocked_pairs(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.safety_blocked_pairs(uuid) TO authenticated, service_role;
CREATE FUNCTION public.safety_pair_blocked(_a uuid,_b uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM user_blocks WHERE (blocker_id=_a AND blocked_id=_b) OR (blocker_id=_b AND blocked_id=_a)) $$;
REVOKE ALL ON FUNCTION public.safety_pair_blocked(uuid,uuid) FROM PUBLIC, anon, authenticated;
CREATE FUNCTION public.safety_visible(_author uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT NOT safety_pair_blocked(auth.uid(),_author) $$;
REVOKE ALL ON FUNCTION public.safety_visible(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.safety_visible(uuid) TO authenticated;
CREATE POLICY "Bilateral check-in visibility" ON public.check_ins AS RESTRICTIVE FOR SELECT TO authenticated USING(safety_visible(user_id));
CREATE POLICY "Bilateral post visibility" ON public.daily_posts AS RESTRICTIVE FOR SELECT TO authenticated USING(safety_visible(user_id));
CREATE POLICY "Bilateral thought visibility" ON public.daily_thoughts AS RESTRICTIVE FOR SELECT TO authenticated USING(safety_visible(user_id));
CREATE POLICY "Bilateral comment visibility" ON public.post_comments AS RESTRICTIVE FOR SELECT TO authenticated USING(safety_visible(user_id));
CREATE POLICY "Bilateral cheer visibility" ON public.post_reactions AS RESTRICTIVE FOR SELECT TO authenticated USING(safety_visible(user_id));
CREATE POLICY "Bilateral comment-like visibility" ON public.comment_likes AS RESTRICTIVE FOR SELECT TO authenticated USING(safety_visible(user_id));
CREATE POLICY "Bilateral chat visibility" ON public.group_messages AS RESTRICTIVE FOR SELECT TO authenticated USING(safety_visible(user_id));
CREATE POLICY "Bilateral chat-reaction visibility" ON public.message_reactions AS RESTRICTIVE FOR SELECT TO authenticated USING(safety_visible(user_id));
CREATE POLICY "Bilateral workout-cheer visibility" ON public.workout_cheers AS RESTRICTIVE FOR SELECT TO authenticated USING(safety_visible(user_id));
CREATE FUNCTION public.validate_safety_interaction() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE author uuid; parent_author uuid; BEGIN
IF TG_TABLE_NAME IN ('post_comments','post_reactions') THEN SELECT user_id INTO author FROM daily_posts WHERE id=NEW.post_id;
ELSIF TG_TABLE_NAME='comment_likes' THEN SELECT user_id INTO author FROM post_comments WHERE id=NEW.comment_id;
ELSIF TG_TABLE_NAME='message_reactions' THEN SELECT user_id INTO author FROM group_messages WHERE id=NEW.message_id;
ELSIF TG_TABLE_NAME='workout_cheers' THEN SELECT user_id INTO author FROM workout_sessions WHERE id=NEW.session_id;
ELSIF TG_TABLE_NAME='member_nudges' THEN IF safety_pair_blocked(NEW.nudger_id,NEW.target_id) THEN RAISE EXCEPTION 'Interaction not allowed'; END IF; RETURN NEW;
END IF;
IF author IS NULL OR safety_pair_blocked(NEW.user_id,author) THEN RAISE EXCEPTION 'Interaction not allowed'; END IF;
IF TG_TABLE_NAME='post_comments' AND NEW.parent_comment_id IS NOT NULL THEN SELECT user_id INTO parent_author FROM post_comments WHERE id=NEW.parent_comment_id; IF safety_pair_blocked(NEW.user_id,parent_author) THEN RAISE EXCEPTION 'Interaction not allowed'; END IF; END IF;
RETURN NEW; END $$;
CREATE TRIGGER safety_comments BEFORE INSERT OR UPDATE ON public.post_comments FOR EACH ROW EXECUTE FUNCTION public.validate_safety_interaction();
CREATE TRIGGER safety_reactions BEFORE INSERT OR UPDATE ON public.post_reactions FOR EACH ROW EXECUTE FUNCTION public.validate_safety_interaction();
CREATE TRIGGER safety_comment_likes BEFORE INSERT OR UPDATE ON public.comment_likes FOR EACH ROW EXECUTE FUNCTION public.validate_safety_interaction();
CREATE TRIGGER safety_message_reactions BEFORE INSERT OR UPDATE ON public.message_reactions FOR EACH ROW EXECUTE FUNCTION public.validate_safety_interaction();
CREATE TRIGGER safety_workout_cheers BEFORE INSERT OR UPDATE ON public.workout_cheers FOR EACH ROW EXECUTE FUNCTION public.validate_safety_interaction();
CREATE TRIGGER safety_nudges BEFORE INSERT ON public.member_nudges FOR EACH ROW EXECUTE FUNCTION public.validate_safety_interaction();
CREATE FUNCTION public.crew_checkin_status() RETURNS TABLE(id uuid,user_id uuid,group_id uuid,checkin_date date,activity text,mood text,note text,photo_url text,created_at timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT c.id,c.user_id,c.group_id,c.checkin_date,c.activity,NULL::text,NULL::text,CASE WHEN c.user_id=auth.uid() THEN c.photo_url ELSE NULL::text END,c.created_at FROM check_ins c WHERE is_group_member(c.group_id,auth.uid()) $$;
REVOKE ALL ON FUNCTION public.crew_checkin_status() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.crew_checkin_status() TO authenticated;
CREATE FUNCTION public.crew_daily_status() RETURNS TABLE(group_id uuid,user_id uuid,local_date date,check_in_missed boolean,check_in_id uuid,morning_ritual_text text,morning_ritual_posted_at timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.group_id,p.user_id,p.local_date,p.check_in_missed,NULL::uuid,NULL::text,NULL::timestamptz FROM daily_posts p WHERE is_group_member(p.group_id,auth.uid()) $$;
REVOKE ALL ON FUNCTION public.crew_daily_status() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.crew_daily_status() TO authenticated;